-- Athena saved query (Product_B2C_Intl)
-- ID: ab8090ee-f9dd-4dec-b2a8-0dc53d86f89a
-- Name: User Behaviour Loop Deeper Funnel UI - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH base AS ( SELECT mri_session_id, CAST(__time AS TIMESTAMP) AS ts_time_utc, event_group, -- Capturing parameters for comparison (CAST(src_id AS VARCHAR) || '-' || CAST(dest_id AS VARCHAR)) as sd_id, CAST(doj AS VARCHAR) as doj_val, route_id_train_no, CASE WHEN event_name = 'payment instrument confirmed' THEN 'payment instrument confirmed' ELSE NULL END AS event_name -- COUNT(DISTINCT mri_session_id) sessions FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-04-27 00:00:00' AND __time < TIMESTAMP '2026-04-28 00:00:00' AND event_src = 'Android' AND header_country = 'IND' AND LOWER(header_bu) = 'bus' AND event_group IN ( 'common_home_screen_load', 'bus_home_screen_load', 'srp_screen_load', 'sl_screen_load', 'cust_info_load', 'payment_screen_load', 'payment_click_event', 'show_ticket_screen_load' ) ), parameter_check AS ( SELECT *, -- Identify the parameters of the very first SRP and SL land in the session FIRST_VALUE(sd_id) OVER (PARTITION BY mri_session_id, event_group ORDER BY ts_time_utc) as first_sd, FIRST_VALUE(doj_val) OVER (PARTITION BY mri_session_id, event_group ORDER BY ts_time_utc) as first_doj, FIRST_VALUE(route_id_train_no) OVER (PARTITION BY mri_session_id, event_group ORDER BY ts_time_utc) as first_route, -- Row number to identify if it's the "First" land ROW_NUMBER() OVER (PARTITION BY mri_session_id, event_group ORDER BY ts_time_utc) as occurrence_rank FROM base ), labeled AS ( SELECT mri_session_id, ts_time_utc, CASE WHEN event_group ='common_home_screen_load' THEN 'Home' WHEN event_group = 'srp_screen_load' THEN CASE WHEN occurrence_rank = 1 THEN 'First SRP' WHEN sd_id = first_sd AND doj_val = first_doj THEN 'Same SD-DOJ SRP' WHEN sd_id <> first_sd AND doj_val = first_doj THEN 'Other SD Same DOJ SRP' WHEN sd_id = first_sd AND doj_val <> first_doj THEN 'Same SD Other DOJ SRP' ELSE 'SRP' END WHEN event_group = 'sl_screen_load' THEN CASE WHEN occurrence_rank = 1 THEN 'First SL' WHEN route_id_train_no = first_route THEN 'Same routeid SL' ELSE 'Different routeid SL' END WHEN event_group = 'bp_dp_screen_load' THEN 'BP_DP_Load' WHEN event_group = 'cust_info_load' THEN 'CI' WHEN event_group = 'payment_screen_load' THEN 'Pay' WHEN event_group = 'payment_click_event' AND event_name = 'payment instrument confirmed' THEN 'AddPay' WHEN event_group = 'show_ticket_screen_load' THEN 'Confirm' -- ELSE event_group END AS step_label FROM parameter_check ), pay_sessions AS ( SELECT DISTINCT mri_session_id FROM labeled WHERE step_label = 'Pay' ), paths AS ( SELECT l.mri_session_id, ARRAY_JOIN(ARRAY_AGG(l.step_label ORDER BY l.ts_time_utc), ' > ') AS behaviour_path FROM labeled l INNER JOIN pay_sessions p ON l.mri_session_id = p.mri_session_id GROUP BY l.mri_session_id ) SELECT behaviour_path, COUNT(*) AS distinct_sessions FROM paths GROUP BY 1 ORDER BY 2 DESC, 1;
